-- ===== U14 vocab 覆盖灌库(volume='9',44词)。分步跑。=====

SELECT 'U14 灌前' tag, count(*) FROM public.junior_vocab WHERE grade=9 AND volume='9' AND unit='U14';

DELETE FROM public.junior_vocab WHERE grade=9 AND volume='9' AND unit='U14';
SELECT 'U14 DELETE后' tag, count(*) FROM public.junior_vocab WHERE grade=9 AND volume='9' AND unit='U14';  -- 应0


SELECT 'U14 INSERT后' tag, count(*) FROM public.junior_vocab WHERE grade=9 AND volume='9' AND unit='U14';  -- 应44
SELECT word, count(*) FROM public.junior_vocab WHERE grade=9 AND volume='9' AND unit='U14' GROUP BY word HAVING count(*)>1;  -- 查重应0行